// Makes every row of a channel left 'sending' due again at at, for a channel
// whose receivers cope with a repeat.
func (q *Queries) RequeueInterruptedNotifications(ctx context.Context, arg RequeueInterruptedNotificationsParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, requeueInterruptedNotifications, arg.At, arg.Channel)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const rescheduleNotification = `-- name: RescheduleNotification :execrows
UPDATE notification_outbox SET status = 'pending', next_attempt_at = ?1
WHERE id = ?2 AND status = 'sending'
`

type RescheduleNotificationParams struct {
	NextAttemptAt sql.NullInt64
	ID            string
}

func (q *Queries) RescheduleNotification(ctx context.Context, arg RescheduleNotificationParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, rescheduleNotification, arg.NextAttemptAt, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const settleNotification = `-- name: SettleNotification :execrows
UPDATE notification_outbox SET status = ?1, next_attempt_at = NULL, finished_at = ?2
WHERE id = ?3 AND status IN ('pending', 'sending', 'held')
`

type SettleNotificationParams struct {
	Status string
	At     sql.NullInt64
	ID     string
}

// Moves a row that has not reached an end state to status.
func (q *Queries) SettleNotification(ctx context.Context, arg SettleNotificationParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, settleNotification, arg.Status, arg.At, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
